function renderCompilerPromptEvidenceContext(retrieval: BrainRetrievalResult): PromptBrainContextRender {
  const resolution = retrieval.contractVersion === "3" ? retrieval.query.projectResolution : undefined;
  return renderPromptEvidenceContext({
    matchedProject: resolution?.status === "matched" ? resolution.page : undefined,
    includeRoute: true,
    diagnostics: retrieval.contractVersion === "3" ? compilerContextDiagnostics(retrieval) : [],
    temporal: retrieval.query.temporal,
    evidence: retrieval.evidence,
    hardBytes: Number.MAX_SAFE_INTEGER,
  });
}

type BrainRetrievalResult = {
  contractVersion: "1" | "3";
  wiki: {
    alias: string;
    schemaVersion: string;
    runtimeContract: string;
  };
  query: {
    question: string;
    shapes: string[];
    stateView: string;
    resolvedSeeds: string[];
    projectResolution?: BrainProjectResolution;
    temporal?: TemporalQuery;
  };
  evidence: BrainCompiledEvidence[];
  omissions: BrainCompilerOmission[];
  coverage: BrainCompilerCoverage;
  budget: BrainCompilerBudget;
  stop: BrainCompilerStop;
  continuation: Record<string, unknown> | null;
  diagnostics: BrainCompilerDiagnostic[];
  reporting: BrainCompilerReporting;
  selectedPages: string[];
  evidenceCount: number;
  candidateCount: number;
};

type PromptBrainContextRender = BrainContextRender & {
  attemptedBytes: number;
  guidanceBytes: number;
  retrievedContextBytes: number;
  framingBytes: number;
};

type BrainContextRender = {
  markdown: string;
  renderedBytes: number;
  truncated: boolean;
};

type BrainProjectResolution =
  | { status: "not_requested" }
  | { status: "unknown" }
  | {
      status: "matched";
      projectId: string;
      page: string;
      matchedBy: "remote" | "alias";
    }
  | {
      status: "ambiguous";
      matchedBy: "remote" | "alias";
      candidates: Array<{ projectId: string; page: string }>;
      candidateCount: number;
    };

type TemporalQuery = Readonly<{
  view: TemporalView;
  request_time: string;
  world_at?: string;
  known_at: string;
  transition?: TemporalTransition;
}>;

type BrainCompiledEvidence = {
  id: string;
  provider: string;
  route: string;
  page: string | null;
  source: string | null;
  locator: Record<string, unknown>;
  content: string;
  roles: string[];
  authoredState: string;
  derivedFlags: string[];
  authoritySignals: string[];
  selectionReasons: string[];
  byteCost: number;
  truncated: boolean;
  atomic: boolean;
};

type BrainCompilerOmission = {
  candidateId: string;
  reason: string;
  estimatedBytes: number | null;
};

type BrainCompilerCoverage = {
  requiredRoles: string[];
  coveredRoles: string[];
  uncoveredRoles: string[];
};

type BrainCompilerBudget = {
  limits: {
    targetBytes: number;
    maxBytes: number;
    targetItems: number;
    maxItems: number;
      maxEstimatedTokens: number | null;
      maxContentBytes: number | null;
      maxDeliveryBytes: number | null;
      deliveryFormat: string | null;
  };
  targetExceededForCoverage: boolean;
  evidenceBytes: number;
  envelopeBytes: number;
  items: number;
  estimatedTokens: number;
  contentBytes: number | null;
  deliveryBytes: number | null;
};

type BrainCompilerStop = {
  reason: string;
  sufficient: boolean;
  detail: string;
};

type BrainCompilerDiagnostic = {
  code: string;
  message: string;
  provider: string | null;
  details: Record<string, unknown>;
};

type BrainCompilerReporting = {
  omissions: { total: number; returned: number };
  diagnostics: { total: number; returned: number };
};

